def test_returns_two_shards_for_star(self) -> None:
    pattern = os.path.join(test_path, "foo@*.bar")
    sf = ShardedFile(pattern)
    self.assertEqual(
        sf.get_filenames(),
        [
            os.path.join(test_path, "foo@00000-of-00002.bar"),
            os.path.join(test_path, "foo@00001-of-00002.bar"),
        ],
    )

